// Code node "Normalise employees"  (mode: Run Once for All Items)
// Input : the pages from the "HR employees" HTTP node (one item per page, each with an "employees" list).
// Output: ONE item { employees, rejected, items_in, items_out } -> feeds "Upsert employees".
// Anything that fails validation goes to "rejected" (it is stored in dead_letter, not dropped).

const employees = [];
const rejected = [];
let itemsIn = 0;

// "2024-01-15" -> "2024-01-15", null/empty -> null, anything else -> undefined (= invalid)
function cleanDate(value) {
  if (value === null || value === undefined || value === '') return null;
  const ok = /^\d{4}-\d{2}-\d{2}$/.test(value) && !Number.isNaN(Date.parse(value));
  return ok ? value : undefined;
}

for (const page of $input.all()) {
  for (const raw of page.json.employees ?? []) {
    itemsIn += 1;

    const email = String(raw.email ?? '').trim().toLowerCase();
    const status = String(raw.employment_status ?? '').trim().toLowerCase();   // ACTIVE -> active
    const startDate = cleanDate(raw.hire_date);
    const endDate = cleanDate(raw.termination_date);

    let reason = null;
    if (!email.includes('@')) reason = 'missing or invalid email';
    else if (!raw.full_name) reason = 'missing name';
    else if (!raw.department) reason = 'missing department';
    else if (!['active', 'terminated'].includes(status)) reason = `unknown status "${raw.employment_status}"`;
    else if (startDate === undefined || endDate === undefined) reason = 'unparseable date';

    if (reason) {
      rejected.push({ item: raw, reason });
      continue;
    }
    employees.push({
      email,
      name: String(raw.full_name).trim(),
      team: String(raw.department).trim(),
      cost_center: raw.cost_center ?? null,
      status,
      start_date: startDate,
      end_date: endDate,
    });
  }
}

return [{ json: { employees, rejected, items_in: itemsIn, items_out: employees.length } }];

// Code node "Normalise accounts"  (mode: Run Once for All Items)
// Reads the four vendor user lists BY NODE NAME, so the HTTP nodes must be called exactly:
//   "Chatterly users", "DesignHub users", "CodeForge members", "MeetSpace members"
// Each vendor uses different field names and date formats; this maps all of them to one shape:
//   { tool, external_id, email, seat_type, status, created_at, last_active_at }
// Output: ONE item { accounts, rejected, vendors, items_in, items_out }.
//   vendors tells the digest which vendors answered, e.g. { chatterly: { ok: true, count: 122 }, ... }

// ---- date helpers: each returns an ISO timestamp string, or null if the value is not a valid date ----
function fromEpochSeconds(n) { return toIso(typeof n === 'number' ? new Date(n * 1000) : null); }
function fromEpochMillis(n) { return toIso(typeof n === 'number' ? new Date(n) : null); }
function fromText(s) {
  // "2024-12-17 09:01:00" (DesignHub, UTC) needs a "T" and a "Z"; "2024-01-17T09:19:00Z" already has them
  if (typeof s !== 'string') return null;
  const text = s.includes('T') ? s : s.replace(' ', 'T') + 'Z';
  return toIso(new Date(text));
}
function toIso(date) { return date && !Number.isNaN(date.getTime()) ? date.toISOString() : null; }

// ---- one entry per vendor: where its list is, and how to turn one record into our shape ----
const VENDORS = [
  {
    tool: 'chatterly', node: 'Chatterly users', list: (p) => p.data,
    map: (u) => ({
      external_id: u.user_id, email: u.email,
      seat_type: u.plan === 'pro' ? 'premium' : 'standard',
      status: u.state === 'active' ? 'active' : 'inactive',
      created_at: fromEpochSeconds(u.created), last_active_at: fromEpochSeconds(u.last_seen),
    }),
  },
  {
    tool: 'designhub', node: 'DesignHub users', list: (p) => p.items,
    map: (u) => ({
      external_id: u.id, email: u.email_address,
      seat_type: u.role === 'creator' ? 'premium' : 'standard',
      status: u.is_active ? 'active' : 'inactive',
      created_at: fromText(u.joined_at), last_active_at: fromText(u.last_login),
    }),
  },
  {
    tool: 'codeforge', node: 'CodeForge members', list: (p) => p.members,
    map: (u) => ({
      external_id: u.member_id, email: u.login,
      seat_type: u.license === 'enterprise' ? 'premium' : 'standard',
      status: u.suspended ? 'inactive' : 'active',
      created_at: fromText(u.joined), last_active_at: fromText(u.last_activity),
    }),
  },
  {
    tool: 'meetspace', node: 'MeetSpace members', list: (p) => p.results,
    map: (u) => ({
      external_id: u.uid, email: u.mail,
      seat_type: u.tier === 'host' ? 'premium' : 'standard',
      status: String(u.status).toUpperCase() === 'ACTIVE' ? 'active' : 'inactive',
      created_at: fromEpochMillis(u.created_at), last_active_at: fromEpochMillis(u.last_active_at),
    }),
  },
];

// Items of a node by name. A vendor that failed has no items (or never ran), which is not an error here.
function pagesOf(nodeName) {
  try { return $(nodeName).all().map((i) => i.json); } catch (e) { return []; }
}

const accounts = [];
const rejected = [];
const vendors = {};
const seen = new Set();
let itemsIn = 0;

for (const vendor of VENDORS) {
  const pages = pagesOf(vendor.node);
  // A page without the vendor's list is an error body (for example {"detail": "Too many requests"}), not data.
  const hasAllLists = pages.every((page) => Array.isArray(vendor.list(page)));
  vendors[vendor.tool] = { ok: pages.length > 0 && hasAllLists, count: 0 };
  if (!hasAllLists) continue;                // do not use half a vendor; the digest reports it as failed

  for (const page of pages) {
    for (const raw of vendor.list(page)) {
      itemsIn += 1;
      const account = { tool: vendor.tool, ...vendor.map(raw) };
      const email = String(account.email ?? '').trim().toLowerCase();

      let reason = null;
      if (!account.external_id) reason = 'missing external_id';
      else if (!email.includes('@')) reason = 'missing or invalid email';
      else if (!account.created_at) reason = 'unparseable created date';
      else if (!account.last_active_at) reason = 'unparseable last-active date';
      else if (seen.has(`${vendor.tool}|${account.external_id}`)) reason = 'duplicate external_id in this run';

      if (reason) {
        rejected.push({ item: { tool: vendor.tool, ...raw }, reason });
        continue;
      }
      seen.add(`${vendor.tool}|${account.external_id}`);
      account.email = email;        // lower-cased and trimmed; a "+alias" is kept on purpose (the audit needs it)
      accounts.push(account);
      vendors[vendor.tool].count += 1;
    }
  }
}

return [{ json: { accounts, rejected, vendors, items_in: itemsIn, items_out: accounts.length } }];

// Code node "Normalise usage"  (mode: Run Once for All Items)
// Reads the four vendor usage lists BY NODE NAME, so the HTTP nodes must be called exactly:
//   "Chatterly usage", "DesignHub usage", "CodeForge activity", "MeetSpace activity"
// Maps every vendor to:  { tool, external_id, day (YYYY-MM-DD), activity_count, spend_usd }
// Output: one item per batch of up to 2000 rows { usage, rejected, items_in, items_out, batch, batches }.
//   "Upsert usage" runs once per batch. rejected, items_in, items_out and bad_pages are the totals (same on every batch).

const BATCH_SIZE = 2000;

// A real calendar day written as YYYY-MM-DD, or null.
function checkDay(text) {
  if (typeof text !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(text)) return null;
  return Number.isNaN(Date.parse(text)) ? null : text;
}
// MeetSpace sends the start of the day as epoch seconds (UTC) -> "YYYY-MM-DD"
function dayFromEpochSeconds(n) {
  return typeof n === 'number' ? checkDay(new Date(n * 1000).toISOString().slice(0, 10)) : null;
}
const round2 = (n) => Math.round(Number(n) * 100) / 100;

const VENDORS = [
  {
    tool: 'chatterly', node: 'Chatterly usage', list: (p) => p.data,
    map: (r) => ({ external_id: r.user_id, day: checkDay(r.date), activity_count: r.requests, spend_usd: r.cost_usd }),
  },
  {
    tool: 'designhub', node: 'DesignHub usage', list: (p) => p.items,
    map: (r) => ({
      external_id: r.id,
      day: checkDay(String(r.day).replace(/^(\d{4})(\d{2})(\d{2})$/, '$1-$2-$3')),   // 20260105 -> 2026-01-05
      activity_count: r.actions, spend_usd: Number(r.spend_cents) / 100,             // cents -> dollars
    }),
  },
  {
    tool: 'codeforge', node: 'CodeForge activity', list: (p) => p.events,
    map: (r) => ({ external_id: r.member_id, day: checkDay(r.date), activity_count: r.contributions, spend_usd: 0 }),
  },
  {
    tool: 'meetspace', node: 'MeetSpace activity', list: (p) => p.results,
    map: (r) => ({ external_id: r.uid, day: dayFromEpochSeconds(r.day_start), activity_count: r.meetings, spend_usd: 0 }),
  },
];

function pagesOf(nodeName) {
  try { return $(nodeName).all().map((i) => i.json); } catch (e) { return []; }
}

const byKey = new Map();      // tool|external_id|day -> row (a repeated row replaces the earlier one)
const rejected = [];
let itemsIn = 0;

let badPages = 0;      // pages without the vendor's list (error bodies); they are skipped and counted

for (const vendor of VENDORS) {
  for (const page of pagesOf(vendor.node)) {
    if (!Array.isArray(vendor.list(page))) { badPages += 1; continue; }
    for (const raw of vendor.list(page)) {
      itemsIn += 1;
      const row = { tool: vendor.tool, ...vendor.map(raw) };

      let reason = null;
      if (!row.external_id) reason = 'missing external_id';
      else if (!row.day) reason = 'unparseable day';
      else if (!Number.isInteger(row.activity_count) || row.activity_count < 0) reason = 'invalid activity_count';
      else if (!Number.isFinite(row.spend_usd) || row.spend_usd < 0) reason = 'invalid spend';

      if (reason) {
        rejected.push({ item: { tool: vendor.tool, ...raw }, reason });
        continue;
      }
      row.spend_usd = round2(row.spend_usd);
      byKey.set(`${row.tool}|${row.external_id}|${row.day}`, row);
    }
  }
}

const rows = [...byKey.values()];
const batches = Math.max(1, Math.ceil(rows.length / BATCH_SIZE));
const out = [];
for (let i = 0; i < batches; i += 1) {
  out.push({
    json: {
      usage: rows.slice(i * BATCH_SIZE, (i + 1) * BATCH_SIZE),
      rejected, items_in: itemsIn, items_out: rows.length, bad_pages: badPages, batch: i + 1, batches,
    },
  });
}
return out;

// Code node "Shape findings"  (mode: Run Once for All Items)
// Input : the rows from the "Audit rules" Postgres node (one item per finding; turn on "Always Output Data").
// Output: ONE item { findings, total, by_type } -> "Upsert findings" gets findings as JSON.
// It drops empty rows, makes sure each finding is unique (the table has a unique key) and counts per type.

const ALLOWED = ['inactive_seat', 'orphaned_account', 'seat_mismatch', 'duplicate_account', 'over_allocation'];
const findings = [];
const byType = {};
const seen = new Set();

for (const item of $input.all()) {
  const f = item.json;
  if (!f.finding_type) continue;                            // the empty item from "Always Output Data"
  if (!ALLOWED.includes(f.finding_type)) continue;

  // Same key as the unique index in audit_findings: type + account (or 0) + email (or '')
  const key = `${f.finding_type}|${f.account_id ?? 0}|${f.employee_email ?? ''}`;
  if (seen.has(key)) continue;
  seen.add(key);

  findings.push({
    finding_type: f.finding_type,
    account_id: f.account_id ?? null,
    employee_email: f.employee_email ?? null,
    severity: f.severity,
    details: f.details ?? {},
  });
  byType[f.finding_type] = (byType[f.finding_type] ?? 0) + 1;
}

return [{ json: { findings, total: findings.length, by_type: byType } }];

// Code node "Build digest"  (mode: Run Once for All Items)
// Input : the rows from "Select new findings" (Always Output Data on, so an empty result is one empty item).
// Output: ONE item { skip, text, blocks, finding_ids }
//   skip = true when there is nothing to post (no new findings and post_empty_digest is false)
// Slack node: Message Type "Blocks", Blocks = {{ JSON.stringify({ blocks: $json.blocks }) }}, Text = {{ $json.text }}

const TOP_N = 5;
const TITLES = {
  orphaned_account: ':ghost: Orphaned accounts',
  inactive_seat: ':zzz: Inactive seats',
  duplicate_account: ':busts_in_silhouette: Duplicate accounts',
  seat_mismatch: ':arrows_counterclockwise: Premium seats barely used',
  over_allocation: ':warning: More accounts than licensed seats',
};
const ORDER = ['orphaned_account', 'over_allocation', 'inactive_seat', 'duplicate_account', 'seat_mismatch'];

const cfg = $('Config').first().json.cfg;
const findings = $input.all().map((i) => i.json).filter((f) => f.finding_type);
const accountsChecked = $('Normalise accounts').first().json.items_out;
const vendors = $('Normalise accounts').first().json.vendors;
const vendorNames = { chatterly: 'Chatterly AI', designhub: 'DesignHub', codeforge: 'CodeForge', meetspace: 'MeetSpace' };

const money = (n) => `$${Math.round(n).toLocaleString('en-US')}`;
const cost = (f) => Number(f.details?.monthly_cost ?? 0);

// "3/4 vendors synced, DesignHub failed"
const failed = Object.entries(vendors).filter(([, v]) => !v.ok).map(([k]) => vendorNames[k]);
const syncLine = failed.length === 0
  ? `${Object.keys(vendors).length}/${Object.keys(vendors).length} vendors synced`
  : `${Object.keys(vendors).length - failed.length}/${Object.keys(vendors).length} vendors synced, ${failed.join(', ')} failed`;

// Nothing new: post one short line, or nothing at all (setting post_empty_digest), unless a vendor failed
if (findings.length === 0) {
  const text = `No new findings, ${accountsChecked} accounts checked. ${syncLine}.`;
  // A failed vendor is always worth a message, even with no new findings.
  const skip = cfg.post_empty_digest !== true && failed.length === 0;
  const blocks = [{ type: 'section', text: { type: 'mrkdwn', text: `${failed.length > 0 ? ':warning: ' : ''}${text}` } }];
  return [{ json: { skip, text, blocks, finding_ids: [] } }];
}

// One line per finding
function line(f) {
  const d = f.details ?? {};
  const who = f.employee_email ?? '';
  switch (f.finding_type) {
    case 'orphaned_account': return `• ${who} — ${d.tool}, ${d.reason === 'terminated' ? 'employee has left' : 'not in HR'}, ${money(cost(f))}/mo`;
    case 'inactive_seat': return `• ${who} — ${d.tool}, last active ${String(d.last_active_at ?? 'never').slice(0, 10)}, ${money(cost(f))}/mo`;
    case 'duplicate_account': return `• ${who} — ${d.tool}, extra account ${d.external_id}, ${money(cost(f))}/mo`;
    case 'seat_mismatch': return `• ${who} — ${d.tool}, premium but ${d.active_days} active days in ${d.window_days}`;
    case 'over_allocation': return `• ${d.tool} — ${d.accounts} accounts for ${d.seats} seats (${d.excess} over, ${money(cost(f))}/mo)`;
    default: return `• ${who}`;
  }
}

const savings = findings.reduce((sum, f) => sum + cost(f), 0);
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'License audit: new findings' } },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: `*${findings.length} new findings*, about *${money(savings)}/month* at stake` },
  },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `${accountsChecked} accounts checked · ${syncLine}` }] },
  { type: 'divider' },
];

for (const type of ORDER) {
  const group = findings.filter((f) => f.finding_type === type);
  if (group.length === 0) continue;
  group.sort((a, b) => cost(b) - cost(a));                 // biggest cost first
  const groupCost = group.reduce((sum, f) => sum + cost(f), 0);
  const shown = group.slice(0, TOP_N).map(line);
  if (group.length > TOP_N) shown.push(`_…and ${group.length - TOP_N} more_`);
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `*${TITLES[type]}* (${group.length}${groupCost > 0 ? `, ${money(groupCost)}/mo` : ''})\n${shown.join('\n')}` },
  });
}

return [{
  json: {
    skip: false,
    text: `License audit: ${findings.length} new findings, about ${money(savings)}/month at stake`,
    blocks,
    finding_ids: findings.map((f) => f.id),
  },
}];

// Ends the run as failed when a source could not be synced, so the error workflow alerts Slack.
const vendors = $('Normalise accounts').first().json.vendors;
const failed = Object.entries(vendors).filter(([, v]) => !v.ok).map(([k]) => k);
const fetchErrors = $('Insert dead_letter').isExecuted ? $('Insert dead_letter').all().length : 0;
if (failed.length > 0 || fetchErrors > 0) {
  const names = failed.length ? ', not synced: ' + failed.join(', ') : '';
  throw new Error(`Usage audit incomplete: ${fetchErrors} fetch(es) failed${names} (see dead_letter)`);
}
return $input.all();
